package com.example.leetcodetrainer.curriculum.domain;
import jakarta.persistence.*; import java.time.*; import java.util.*;
@Entity @Table(name="learning_mode_definition") public class LearningModeDefinition { @Id private UUID id; @Column(nullable=false,unique=true) private String code; @Column(nullable=false) private String displayName; @Lob private String description; private int displayOrder; private boolean active; private int contentVersion; private Instant createdAt,updatedAt; protected LearningModeDefinition(){} public UUID getId(){return id;} public String getCode(){return code;} public String getDisplayName(){return displayName;} public String getDescription(){return description;} public int getDisplayOrder(){return displayOrder;} public boolean isActive(){return active;} }
